import { i18n } from './index';
import { consoleLifecycleMessages } from './console-lifecycle';

// These exact strings are generated by LT's unchanged stream client. Unknown
// server gap details and original diagnostics remain verbatim.
const notices = new Map<string, string>(Object.entries(consoleLifecycleMessages)
  .filter(([key]) => key.startsWith('console.notice.'))
  .map(([key, values]) => [values[0], key]));
export function consoleNotice(value: string): string {
  const key = notices.get(value);
  return key ? i18n.t(key) : value;
}
